-- Housing districts + city overview batch: 9 Polish cities (65 districts)
-- Generated automatically. Run in Supabase SQL Editor.

-- 1. Extend housing_districts with room-tier rent breakdown + purchase price
alter table public.housing_districts
  add column if not exists rent_studio_min numeric,
  add column if not exists rent_studio_avg numeric,
  add column if not exists rent_studio_max numeric,
  add column if not exists rent_2room_min numeric,
  add column if not exists rent_2room_avg numeric,
  add column if not exists rent_2room_max numeric,
  add column if not exists rent_3room_min numeric,
  add column if not exists rent_3room_avg numeric,
  add column if not exists rent_3room_max numeric,
  add column if not exists purchase_price_m2 numeric;

-- 2. City-level overview table (one row per city)
create table if not exists public.housing_city_overview (
  city text primary key,
  population text,
  districts_note text,
  transport text,
  summary text,
  rent_studio_avg numeric,
  rent_2room_avg numeric,
  rent_3room_avg numeric,
  rent_4plus_avg numeric,
  rent_city_avg numeric
);

alter table public.housing_city_overview enable row level security;
drop policy if exists "housing_city_overview_select" on public.housing_city_overview;
create policy "housing_city_overview_select" on public.housing_city_overview for select using (true);

-- 3. Replace district rows for all 9 cities
