values
  ('Варшава', 'Śródmieście', '4 130 - 8 500 zł', NULL, false, NULL, 3510, 4130, 4750, 3670, 4320, 4960, 7230, 8500, 9780, 25322),
  ('Варшава', 'Żoliborz', '3 820 - 7 850 zł', NULL, false, NULL, 3240, 3820, 4390, 3390, 3990, 4580, 6670, 7850, 9030, 23379),
  ('Варшава', 'Wola', '3 690 - 7 600 zł', 'Высокий. Самый динамичный деловой район последних лет — небоскрёбы у Ronda Daszyńskiego, много новостроек. Метро M2 прямо в центр. Популярен у молодых профессионалов и иностранных специалистов, много новых апартаментов под аренду.', true, 2, 3140, 3690, 4250, 3280, 3860, 4440, 6460, 7600, 8740, 22622),
  ('Варшава', 'Ursynów', '3 300 - 6 800 zł', NULL, false, NULL, 2810, 3300, 3800, 2930, 3450, 3970, 5780, 6800, 7810, 20236),
  ('Варшава', 'Wilanów', '3 230 - 6 650 zł', NULL, false, NULL, 2750, 3230, 3720, 2870, 3380, 3880, 5650, 6650, 7640, 19797),
  ('Варшава', 'Mokotów', '3 220 - 6 620 zł', 'Средне-высокий. Одна из крупнейших и самых разных дзельниц: престижный Старый Мокотув и Sielce соседствуют с деловым Служевцем (много офисов и IT-компаний). Метро M1, трамваи, отличная инфраструктура. Хороший баланс для семей и для тех, кто работает в бизнес-центрах.', true, 1, 2740, 3220, 3700, 2860, 3360, 3870, 5630, 6620, 7620, 19728),
  ('Варшава', 'Praga-Północ', '3 060 - 6 290 zł', NULL, false, NULL, 2600, 3060, 3510, 2710, 3190, 3670, 5340, 6290, 7230, 18726),
  ('Варшава', 'Ochota', '3 020 - 6 220 zł', 'Средний. Граничит со Средместьем, при этом заметно дешевле. Много кварталов застройки времён ПНР, развитая инфраструктура, рядом Варшавский университет и Политехника — популярно у студентов и молодых семей.', true, 3, 2570, 3020, 3470, 2680, 3160, 3630, 5280, 6220, 7150, 18514),
  ('Варшава', 'Praga-Południe', '3 000 - 6 160 zł', 'Средний. Самая населённая дзельница Варшавы. Разная застройка — от старых домов Грохова до новостроек у Каменка и престижной Саской Кемпы. Метро M2, хороший выбор бюджета жилья.', true, 4, 2550, 3000, 3440, 2660, 3130, 3600, 5240, 6160, 7090, 18354),
  ('Варшава', 'Bielany', '3 000 - 6 160 zł', 'Ниже среднего. Спальный район со метро (M1), много зелени, спокойнее центра, активно строится новое жильё — хороший вариант для семей с детьми, где цена аренды важнее близости к центру.', true, 5, 2550, 3000, 3440, 2660, 3130, 3600, 5240, 6160, 7090, 18352),
  ('Варшава', 'Włochy', '2 790 - 5 740 zł', NULL, false, NULL, 2370, 2790, 3210, 2480, 2910, 3350, 4880, 5740, 6600, 17080),
  ('Варшава', 'Bemowo', '2 760 - 5 680 zł', 'Ниже среднего. Спальный район, много зелени, спокойнее центра, активно строится новое жильё — хороший вариант для семей с детьми, где цена аренды важнее близости к центру.', true, 7, 2350, 2760, 3180, 2450, 2880, 3320, 4830, 5680, 6530, 16922),
  ('Варшава', 'Wesoła', '2 510 - 5 160 zł', NULL, false, NULL, 2130, 2510, 2880, 2230, 2620, 3010, 4380, 5160, 5930, 15358),
  ('Варшава', 'Ursus', '2 450 - 5 030 zł', 'Ниже среднего. Спальный район с хорошей ж/д связью, много зелени, спокойнее центра, активно строится новое жильё — хороший вариант для семей с детьми, где цена аренды важнее близости к центру.', true, 6, 2080, 2450, 2810, 2170, 2550, 2940, 4280, 5030, 5790, 14981),
  ('Варшава', 'Targówek', '2 430 - 5 000 zł', NULL, false, NULL, 2070, 2430, 2800, 2160, 2540, 2920, 4250, 5000, 5750, 14898),
  ('Варшава', 'Rembertów', '2 310 - 4 760 zł', NULL, false, NULL, 1970, 2310, 2660, 2050, 2420, 2780, 4050, 4760, 5480, 14180),
  ('Варшава', 'Wawer', '2 290 - 4 710 zł', NULL, false, NULL, 1950, 2290, 2640, 2030, 2390, 2750, 4010, 4710, 5420, 14041),
  ('Варшава', 'Białołęka', '2 280 - 4 690 zł', 'Самый доступный. Крупнейшая зона новостроек на севере города, самые низкие цены в Варшаве, но метро пока не доходит — дорога до центра автобусом или машиной. Подходит тем, кто готов пожертвовать временем в дороге ради цены.', true, 8, 1940, 2280, 2620, 2020, 2380, 2740, 3990, 4690, 5390, 13963),
  ('Краков', 'Stare Miasto', '3 140 - 5 550 zł', NULL, false, NULL, 2660, 3140, 3610, 3380, 3980, 4570, 4720, 5550, 6380, 20889),
  ('Краков', 'Grzegórzki', '3 020 - 5 350 zł', NULL, false, NULL, 2570, 3020, 3480, 3260, 3840, 4410, 4550, 5350, 6160, 20151),
  ('Краков', 'Zwierzyniec', '2 960 - 5 230 zł', NULL, false, NULL, 2510, 2960, 3400, 3190, 3750, 4310, 4450, 5230, 6020, 19690),
  ('Краков', 'Krowodrza', '2 720 - 4 810 zł', '3 200–4 300 zł. Студенческое сердце Кракова — рядом кампус AGH и Студенческий городок, крупнейший в Польше. Много объявлений именно под долгосрочную студенческую аренду, стабильный спрос круглый год. Хорошая транспортная связь и инфраструктура.', true, 2, 2310, 2720, 3130, 2930, 3450, 3970, 4090, 4810, 5540, 18116),
  ('Краков', 'Podgórze', '2 590 - 4 580 zł', '3 000–4 000 zł. Лучший баланс цены, инфраструктуры и близости к центру — через мост Пилсудского пешком до Рынка. Бывший рабочий район, сейчас модный: галереи, Zabłocie, кафе. Активно растут цены, хороший выбор и на вторичном, и на новом рынке.', true, 1, 2200, 2590, 2980, 2790, 3280, 3780, 3890, 4580, 5270, 17245),
  ('Краков', 'Bronowice', '2 560 - 4 540 zł', NULL, false, NULL, 2180, 2560, 2950, 2770, 3250, 3740, 3860, 4540, 5220, 17089),
  ('Краков', 'Prądnik Czerwony', '2 490 - 4 410 zł', NULL, false, NULL, 2120, 2490, 2860, 2690, 3160, 3630, 3750, 4410, 5070, 16594),
  ('Краков', 'Łagiewniki-Borek Fałęcki', '2 340 - 4 140 zł', NULL, false, NULL, 1990, 2340, 2690, 2520, 2970, 3420, 3520, 4140, 4770, 15597),
  ('Краков', 'Czyżyny', '2 330 - 4 130 zł', '2 900–3 900 zł. Современный район на востоке с новостройками, торговыми центрами (M1, Serenada), Музеем авиации и кампусом Политехники. Активная застройка, удобный транспорт.', true, 4, 1980, 2330, 2680, 2510, 2960, 3400, 3510, 4130, 4750, 15531),
  ('Краков', 'Podgórze Duchackie', '2 330 - 4 120 zł', NULL, false, NULL, 1980, 2330, 2680, 2510, 2950, 3390, 3500, 4120, 4740, 15501),
  ('Краков', 'Prądnik Biały', '2 320 - 4 110 zł', '2 800–3 800 zł. Спокойный, зелёный, доступный по цене район с новыми жилыми комплексами и хорошей связью с центром и объездной дорогой. Много новостроек разного уровня — хороший выбор для семей.', true, 3, 1970, 2320, 2670, 2500, 2940, 3390, 3490, 4110, 4730, 15466),
  ('Краков', 'Dębniki', '2 310 - 4 090 zł', NULL, false, NULL, 1960, 2310, 2660, 2490, 2930, 3370, 3480, 4090, 4700, 15396),
  ('Краков', 'Mistrzejowice', '2 200 - 3 890 zł', NULL, false, NULL, 1870, 2200, 2530, 2370, 2790, 3210, 3310, 3890, 4470, 14641),
  ('Краков', 'Bieżanów-Prokocim', '2 090 - 3 700 zł', NULL, false, NULL, 1780, 2090, 2400, 2250, 2650, 3050, 3150, 3700, 4260, 13929),
  ('Краков', 'Bieńczyce', '2 080 - 3 670 zł', NULL, false, NULL, 1760, 2080, 2390, 2240, 2630, 3030, 3120, 3670, 4230, 13830),
  ('Краков', 'Nowa Huta', '2 040 - 3 620 zł', NULL, false, NULL, 1740, 2040, 2350, 2200, 2590, 2980, 3080, 3620, 4160, 13618),
  ('Краков', 'Wzgórza Krzesławickie', '2 030 - 3 590 zł', NULL, false, NULL, 1720, 2030, 2330, 2190, 2570, 2960, 3050, 3590, 4130, 13520),
  ('Краков', 'Swoszowice', '2 020 - 3 570 zł', NULL, false, NULL, 1710, 2020, 2320, 2170, 2560, 2940, 3030, 3570, 4100, 13434),
  ('Вроцлав', 'Stare Miasto', '3 000 - 4 910 zł', 'Самый дорогой. Исторический центр — Rynek, набережная Одры, лучшая инфраструктура развлечений и общепита. Компактно, всё в пешей доступности, но и цены, и шум по вечерам выше, чем в остальном городе.', true, 2, 2550, 3000, 3450, 3150, 3700, 4260, 4180, 4910, 5650, NULL),
  ('Вроцлав', 'Śródmieście', '2 760 - 4 520 zł', 'Спокойный центр. Отличный баланс: рядом с центром, но тише. Здесь Plac Grunwaldzki — студенческий кластер у главного кампуса Вроцлавского университета, и Biskupin — престижный виллы-район у ботанического сада.', true, 3, 2350, 2760, 3180, 2900, 3410, 3920, 3840, 4520, 5200, NULL),
  ('Вроцлав', 'Krzyki', '2 520 - 4 130 zł', 'Самый популярный у экспатов. Крупнейший по площади район на юге города. Внутри — очень разные по цене зоны: престижный Bartoszowice и Klecina с новостройками премиум-класса, и более доступный Jagodno с массовой новой застройкой. Много зелени, торговых центров, хорошее трамвайное сообщение.', true, 1, 2140, 2520, 2900, 2640, 3110, 3580, 3510, 4130, 4750, NULL),
  ('Вроцлав', 'Fabryczna', '2 040 - 3 340 zł', 'Доступный, растущий. Самый большой по площади район, много новостроек в Muchoborze, Kozanowie и Żerniki. Дальше от центра, но дешевле и активно застраивается новой инфраструктурой (школы, детские сады, ТЦ).', true, 4, 1740, 2040, 2350, 2140, 2520, 2900, 2840, 3340, 3840, NULL),
  ('Гданьск', 'Wrzeszcz', '2 610 - 4 490 zł', '3 000–3 800 zł. Лучший баланс цены, транспорта и близости к морю — второй по значению деловой центр города, узел SKM, много магазинов, кафе, поликлиник. Популярен у молодых профессионалов.', true, 1, 2220, 2610, 3000, 2800, 3290, 3780, 3820, 4490, 5170, NULL),
  ('Гданьск', 'Oliwa', '2 840 - 4 890 zł', '3 200–4 200 zł. Зелёный престижный район у подножия лесистых холмов, рядом Олива парк, кафедральный собор, близко к бизнес-центрам Alchemia. Один из самых спокойных и приятных для жизни районов города.', true, 2, 2420, 2840, 3270, 3040, 3580, 4120, 4160, 4890, 5620, NULL),
  ('Гданьск', 'Przymorze', '2 650 - 4 560 zł', '3 000–3 900 zł. Популярный приморский район с развитой инфраструктурой, длинный пляж в пешей доступности, застройка — блочные дома 70-80-х годов и новостройки у моря.', true, 3, 2250, 2650, 3050, 2840, 3340, 3840, 3880, 4560, 5240, NULL),
  ('Гданьск', 'Piecki-Migowo (Morena)', '2 380 - 4 100 zł', '2 700–3 500 zł. Современный район с активной новой застройкой и удобным сообщением, чуть дальше от моря — соответственно доступнее по цене.', true, 4, 2020, 2380, 2740, 2550, 3000, 3450, 3480, 4100, 4710, NULL),
  ('Познань', 'Jeżyce', '2 400 - 3 960 zł', 'Модный, выше среднего. Один из самых атмосферных районов — старая застройка, кафе, рынок Jeżycki, рядом ботанический сад и кампус университета. Активная городская жизнь, популярен у молодёжи и творческих профессий.', true, 1, 2040, 2400, 2760, 2580, 3030, 3480, 3360, 3960, 4550, NULL),
  ('Познань', 'Grunwald', '2 190 - 3 610 zł', 'Семейный, спокойный. Тихий зелёный район с хорошими школами и удобным транспортом, застройка от довоенных вилл до современных жилых комплексов. Одна из лучших опций для семей с детьми.', true, 2, 1860, 2190, 2520, 2350, 2770, 3180, 3070, 3610, 4160, NULL),
  ('Познань', 'Wilda', '2 080 - 3 440 zł', 'Растущий, близко к центру. Южный район у самого центра, активно обновляется, соседствует с рекой Вартой и стадионом. Хорошая альтернатива дорогому Старому Място.', true, 4, 1770, 2080, 2400, 2240, 2640, 3030, 2920, 3440, 3960, NULL),
  ('Познань', 'Rataje (część Nowe Miasto)', '1 670 - 2 750 zł', 'Доступный. Крупнейший спальный район на восточном берегу Варты, застройка эпохи ПНР плюс новые кварталы. Быстрый трамвай до центра, много магазинов и ТЦ (Franowo), цены заметно ниже средних по городу.', true, 3, 1420, 1670, 1920, 1790, 2110, 2420, 2340, 2750, 3170, NULL),
  ('Щецин', 'Śródmieście', '2 560 - 4 340 zł', 'Выше среднего. Центр города с лучшей инфраструктурой, транспортом и историческим наследием (Замок Поморских Князей, набережная Хакена). Компактно и удобно, но и дороже остальных районов.', true, 1, 2180, 2560, 2950, 2700, 3170, 3650, 3690, 4340, 4990, NULL),
  ('Щецин', 'Pogodno', '2 340 - 3 960 zł', 'Средне-высокий. Один из самых зелёных и престижных жилых районов, вилла-застройка и спокойная атмосфера, популярен у семей с детьми.', true, 2, 1990, 2340, 2690, 2460, 2900, 3330, 3370, 3960, 4560, NULL),
  ('Щецин', 'Warszewo', '2 230 - 3 770 zł', 'Средний, растущий. Активно застраиваемый новый район на северо-западе, современные жилые комплексы, ближе к лесопарковой зоне.', true, 3, 1890, 2230, 2560, 2340, 2760, 3170, 3210, 3770, 4340, NULL),
  ('Щецин', 'Niebuszewo', '1 890 - 3 210 zł', 'Доступный. Хорошее сочетание цены, транспорта и спокойной атмосферы, преимущественно застройка середины XX века.', true, 4, 1610, 1890, 2180, 1990, 2340, 2700, 2730, 3210, 3690, NULL),
  ('Лодзь', 'Śródmieście', '2 080 - 3 580 zł', 'Выше среднего. Исторический центр с лучшей инфраструктурой, знаменитой Piotrkowska и самым большим выбором жилья — от отреставрированных фабричных лофтов до классических квартир. Оживлённо, много кафе и культурной жизни, но и выше уровень шума.', true, 1, 1770, 2080, 2400, 2290, 2700, 3100, 3040, 3580, 4120, NULL),
  ('Лодзь', 'Widzew', '1 810 - 3 110 zł', 'Средний. Современные жилые кварталы, много зелени (парки Zdrowie, Źródliska) и хорошее трамвайное сообщение с центром. Популярен у семей, спокойнее Средместья.', true, 2, 1540, 1810, 2080, 1990, 2340, 2700, 2650, 3110, 3580, NULL),
  ('Лодзь', 'Polesie', '1 810 - 3 110 zł', 'Средний. Тихий, преимущественно жилой район рядом с центром — подходит и семьям, и студентам благодаря близости к университетам и Политехнике Лодзинской.', true, 3, 1540, 1810, 2080, 1990, 2340, 2700, 2650, 3110, 3580, NULL),
  ('Лодзь', 'Bałuty', '1 450 - 2 490 zł', 'Доступный. Самый крупный по населению район, доступные цены и развитая базовая инфраструктура (магазины, школы, поликлиники). Часть района — старая, депрессивная застройка, часть — новые спальные кварталы; стоит выбирать конкретную улицу.', true, 4, 1230, 1450, 1670, 1590, 1880, 2160, 2120, 2490, 2860, NULL),
  ('Люблин', 'Śródmieście', '2 470 - 3 470 zł', 'Выше среднего. Центр с университетами, историческим Старым Городом, кафе и лучшей инфраструктурой. Много студенческой аренды, оживлённая жизнь.', true, 1, 2100, 2470, 2840, 2530, 2980, 3420, 2950, 3470, 3990, NULL),
  ('Люблин', 'Czechów', '2 150 - 3 020 zł', 'Средний. Спокойный зелёный район, популярный среди семей, застройка от 70-х годов до новых комплексов, хорошая транспортная связь с центром.', true, 2, 1830, 2150, 2470, 2200, 2590, 2980, 2570, 3020, 3470, NULL),
  ('Люблин', 'Węglin', '2 150 - 3 020 zł', 'Средний. Современные жилые кварталы и удобное сообщение, один из активно застраиваемых районов последних лет.', true, 3, 1830, 2150, 2470, 2200, 2590, 2980, 2570, 3020, 3470, NULL),
  ('Люблин', 'Czuby', '1 830 - 2 570 zł', 'Доступный. Один из лучших районов по соотношению цены и качества жизни, крупный жилой массив с развитой инфраструктурой (школы, поликлиники, ТЦ).', true, 4, 1550, 1830, 2100, 1870, 2200, 2530, 2180, 2570, 2950, NULL),
  ('Катовице', 'Brynów-Osiedle Zgrzebnioka', '2 190 - 3 610 zł', 'Престижный современный. Один из наиболее позитивно оцениваемых жителями районов, рядом парки и зелёные зоны, современная застройка.', true, 4, 1860, 2190, 2510, 2460, 2890, 3330, 3070, 3610, 4150, NULL),
  ('Катовице', 'Śródmieście', '2 000 - 3 310 zł', 'Центр, средне-высокий. Центр города с лучшей транспортной доступностью, деловой и торговой инфраструктурой (Rynek, Silesia City Center рядом). Из-за смешанной старой застройки воспринимается неоднозначно — часть кварталов требует ремонта.', true, 1, 1700, 2000, 2300, 2260, 2650, 3050, 2810, 3310, 3810, NULL),
  ('Катовице', 'Koszutka', '1 910 - 3 160 zł', 'Тихий, рядом с центром. Компактный район примыкающий к центру, с хорошей инфраструктурой и неплохой репутацией у жителей, удобно добираться пешком до делового центра.', true, 3, 1630, 1910, 2200, 2150, 2530, 2910, 2680, 3160, 3630, NULL),
  ('Катовице', 'Ligota-Panewniki', '1 820 - 3 010 zł', 'Любимый у студентов и семей. Зелёный район с хорошей репутацией у жителей (один из лидеров по индексу удовлетворённости Otodom), рядом кампусы вузов, спокойная жилая застройка.', true, 2, 1550, 1820, 2100, 2050, 2410, 2770, 2560, 3010, 3460, NULL),
  ('Катовице', 'Osiedle Tysiąclecia/Witosa', '1 640 - 2 710 zł', 'Лучшая репутация по опросам жителей. По независимому рейтингу районов Otodom (NPS) именно эти два спальных района получили самые высокие оценки удовлетворённости жизнью среди всех районов Катовице — хорошая инфраструктура спальных кварталов при разумных ценах.', true, 5, 1390, 1640, 1890, 1850, 2170, 2500, 2300, 2710, 3110, NULL);

-- 4. Replace city overview rows
delete from public.housing_city_overview where city in ('Варшава', 'Вроцлав', 'Гданьск', 'Катовице', 'Краков', 'Лодзь', 'Люблин', 'Познань', 'Щецин');

insert into public.housing_city_overview
  (city, population, districts_note, transport, summary,
   rent_studio_avg, rent_2room_avg, rent_3room_avg, rent_4plus_avg, rent_city_avg)
values
  ('Варшава', '~1,86 млн жителей, крупнейшая агломерация Польши', '18 официальных дзельниц (административных районов)', '2 линии метро (M1 — север-юг, M2 — запад-восток), густая сеть трамваев и автобусов, быстрые электрички SKM/KM в дальние районы. Метро — главный фактор цены: районы без станции метро (Białołęka, Wawer, Wilanów) заметно дешевле при сравнимом расстоянии от центра.', 'Столица и самый дорогой город Польши, но и с самым большим рынком труда, международными компаниями и наибольшим выбором жилья. Разброс цен между районами здесь самый большой в стране: разница между центром и окраиной — более 11 000 zł/m² в цене покупки, что напрямую отражается и на аренде.', 2960, 3092, 6090, 10075, 4868),
  ('Краков', '~800 тыс. жителей, второй по величине город Польши', '18 официальных дзельниц', 'Метро отсутствует — основа транспорта это трамваи (самая развитая трамвайная сеть в Польше) и автобусы. Центр компактный, большинство районов в пределах 20-30 минут трамваем от Рынка.', 'Культурная столица Польши, крупнейший студенческий центр (более 10 университетов, включая Ягеллонский), огромный рынок краткосрочной и студенческой аренды. Второй по дороговизне город после Варшавы.', 2420, 3070, 4284, 6131, 3158),
  ('Вроцлав', '~675 тыс. жителей, столица Нижней Силезии', '5 официальных дзельниц (внутри — десятки osiedla)', 'Метро нет, но очень развитая и разветвлённая трамвайная сеть плюс автобусы. Центр (Stare Miasto/Śródmieście) пешеходный и компактный.', 'Один из самых востребованных городов у экспатов и IT-специалистов — крупный кластер международных компаний (Google, IBM, Nokia и др.), много иностранных студентов и рабочих-релокантов. Цены на аренду — в топ-4 по стране.', 2402, 2962, 3931, 5406, 3136),
  ('Гданьск', '~470 тыс. жителей, ядро Труймясто (Гданьск-Сопот-Гдыня)', '32 официальные дзельницы (самое дробное деление среди крупных городов Польши)', 'Трамваи, автобусы и пригородная электричка SKM, которая связывает всё Труймясто вдоль побережья — удобно жить дальше от центра, если рядом станция SKM.', 'Портовый и туристический город на Балтике, один из самых дорогих рынков аренды в стране наравне с Варшавой и Краковом — сказывается близость моря, туристический спрос и IT-кластер (Amazon, Intel и др.).', 2448, 3085, 4212, 5370, 3187),
  ('Познань', '~530 тыс. жителей', '5 официальных дзельниц (внутри — 42 osiedla)', 'Трамваи и автобусы, отдельная линия скоростного трамвая (Poznański Szybki Tramwaj) на Rataje и в новые районы. Метро отсутствует.', 'Деловой и университетский центр Великопольши с одним из самых низких уровней безработицы в стране. Компактный, аккуратный город с сильной студенческой средой.', 2085, 2635, 3441, 4401, 2756),
  ('Щецин', '~390 тыс. жителей, крупнейший портовый город на северо-западе', '4 официальные дзельницы (внутри — множество osiedla)', 'Трамвайная сеть плюс автобусы, город растянут вдоль реки — время в пути между районами больше среднего по стране.', 'Приграничный с Германией город на реке Одра, спокойный рынок аренды со средними по стране ценами, но заметным приростом в последние годы.', 2229, 2758, 3774, 4891, 2837),
  ('Лодзь', '~650 тыс. жителей, третий город Польши', '5 официальных дзельниц (внутри каждой — десятки более мелких osiedla)', 'Трамвайная сеть — основа транспорта, плюс автобусы. Компактный город, из большинства районов до центра 20-25 минут.', 'Самый доступный по жилью крупный город Польши — аренда в среднем почти вдвое дешевле варшавской. Бывший текстильный центр, сейчас активно ревитализируется (ул. Piotrkowska, комплекс Manufaktura), растущий IT- и BPO-сектор.', 1813, 2345, 3112, 3907, 2413),
  ('Люблин', '~330 тыс. жителей, крупнейший город восточной Польши', '27 официальных osiedla (жилых микрорайонов)', 'Автобусы и троллейбусы (одна из немногих троллейбусных сетей в Польше), трамваев и метро нет. Город компактный.', 'Крупный университетский центр восточной Польши (5 вузов, включая старейший медицинский университет региона), один из самых доступных по цене крупных городов страны.', 2150, 2588, 3020, 3362, 2547),
  ('Катовице', '~290 тыс. жителей, столица Силезского воеводства, ядро крупнейшей в Польше агломерации (~2,2 млн жителей)', '22 официальные jednostki pomocnicze (районы)', 'Автобусы и трамваи (в т.ч. система Górnośląsko-Zagłębiowska Metropolia, связывающая Катовице с соседними городами агломерации). Южные и часть западных районов имеют более редкое автобусное сообщение — интервалы могут доходить до 40 минут.', 'Промышленный и деловой центр Верхней Силезии с одними из самых доступных цен на жильё среди крупных городов Польши при этом с сильным рынком труда (BPO/SSC-центры, автомобильная и IT-индустрия).', 1822, 2412, 3008, 4163, 2388);